def model_en(idx: int) -> dict:
    name, short, detailed, phases, outputs, duration = MODELS_EN[idx - 1]
    return {'name': name, 'short_desc': short, 'detailed_desc': detailed,
            'phases': [{'title': t, 'desc': d} for t, d in phases], 'outputs': outputs, 'duration': duration}
